  "220":{"n":"Serpent's Kiss","k":"Passive item","d":"Tears have a chance to apply a poison effect to enemies. Isaac poisons enemies on contact. Poisoned enemies have a chance to drop a Black Heart when killed.","q":"The kiss of death","w":"Serpent's Kiss","i":"3db64f17aee90f817bd1fba5026b22db0569fda4.jpg"},
  "221":{"n":"Succubus","k":"Passive item","d":"Spawns a flying familiar that bounces around the room with a black aura, dealing rapid damage to any enemies inside it. While standing in the aura, Isaac gains a 1.5× tear damage multiplier.","q":"Damage booster","w":"Succubus","i":"2f9d82e69c0ee7a241a3eb6e21913a0ee3e21f80.jpg"},
