  "223":{"n":"Goat Head Baby","k":"Co-op baby","d":"Co-op baby. Occasionally briefly gives Isaac the Goat Head effect, guaranteeing that a Devil room or angel room will open if a boss room is completed while the effect is active.","w":"Co-op","i":"e1a481b8748663b54a5bcc54b885c599cbcad910.jpg"},
