  "284":{"n":"Silver Dollar","k":"Trinket","d":"Shops appear in Chapter 4.","q":"Feels lucky...","w":"Silver Dollar","i":"116eaf688c8d0d7076a2b96d5b15dd8f66afb67b.jpg"},
  "285":{"n":"Shade","k":"Passive item","d":"Spawns a shadow familiar that follows Isaac's movements on a 1 second delay and deals contact damage to enemies. After dealing enough damage, it is absorbed by Isaac and spawns friendly My Shadows.","q":"It follows","w":"Shade","i":"aae80fcbafc5f4a153e1abfb6407ab9db78a011d.jpg"},
  "286":{"n":"King Baby","k":"Passive item","d":"Spawns a familiar that follows Isaac and makes other familiars follow it. While firing tears, other familiars stop moving.","w":"King Baby","i":"ac0637ec50e54de2cc7d533a60c918cfcdc40488.jpg"},
  "287":{"n":"Bloody Crown","k":"Trinket","d":"Treasure Rooms appear in Chapter 4.","q":"Drips with blood...","w":"Bloody Crown","i":"5da7fbf538d190b94022fcca3d95eb8df3407f6a.jpg"},
  "288":{"n":"Dull Razor","k":"Active item","d":"Hurts Isaac without depleting health, activating any items that trigger upon taking damage.","q":"I feel numb...","w":"Dull Razor","i":"13d24b934dc07ba670bc8b0fa1e9e51605addb17.jpg"},
  "289":{"n":"Eden's Soul","k":"Active item","d":"Spawns two random items from the current room's Item Pool and then disappears. Starts with no charges.","q":"...","w":"Eden's Soul","i":"b9aa67d2f397217304850d45097284818a741994.jpg"},
  "290":{"n":"Dark Prince's Crown","k":"Passive item","d":"When at exactly one Red Heart, +0.75 tears, +1.5 range, and +0.2 shot speed. When at exactly one Red Heart, +2 fire rate, +1.5 range, and +0.2 shot speed.","q":"Loss is power","w":"Dark Prince's Crown","i":"af078a5a7ed7e6751b7ae527e7ee4dd20dc72f42.jpg"},
