  "292":{"n":"Euthanasia","k":"Passive item","d":"Adds a luck-based chance to fire needles that instantly kill basic enemies and deal triple damage to bosses. If a needle kills an enemy, it bursts into more tears/needles.","q":"Needle shot","w":"Euthanasia","i":"c78629f8b190c84294669ba0f987230e32982164.jpg"},
  "293":{"n":"Holy Card","k":"Card","d":"Grants a shield that blocks the next hostile damage that would be taken in the current room. Has a chance to spawn another Holy Card on use. Grants a shield that blocks the next hostile damage that would be taken.","q":"You feel protected","w":"Holy Card","i":"5dd94da241d350b3ba5077fdee63e36518fe54be.jpg"},
  "294":{"n":"Crooked Penny","k":"Active item","d":"Has a 50% chance to double all items, Chest, trinkets, and pickups in the room. If the effect fails, spawns a Penny and the other items and pickups disappear.","q":"50/50","w":"Crooked Penny","i":"129f05e3d80c20c364c69e7f1522455de23b2285.jpg"},
  "295":{"n":"Void","k":"Active item","d":"Consumes all pedestal items in the room. Activated items will have their effects added to Void, and passive items will grant random stat upgrades.","q":"Consume","w":"Void","i":"248c58f79392da7ca962035bfa6fd9e31d383cda.jpg"},
  "296":{"n":"D1","k":"Active item","d":"Duplicates a random pickup in the room. The new pickup may be different than the original (i.e. a different card, etc).","q":"What will it be?","w":"D1","i":"826818fe27d5aad945dc533847fa09b2787aedf3.jpg"},
  "297":{"n":"Glyph of Balance","k":"Passive item","d":"Grants 2 Soul Hearts and modifies drops from Champion monsters based on certain conditions. Also modifies room clear drops.","q":"A gift from above","w":"Glyph of Balance","i":"adee15f2e85d4fd0f2e07c7d83cb7ff804301ffc.jpg"},
