  "301":{"n":"Stem Cell","k":"Trinket","d":"Heals Isaac for a Half Red Heart upon traveling to the next floor. Heals 50% of Isaac's empty Red Heart containers upon traveling to the next floor.","q":"Regen!","w":"Stem Cell","i":"fba2be9412e8485df2ca47ad6e9c827e44816a1b.jpg"},
