  "307":{"n":"Dad's Lost Coin","k":"Passive item","d":"+1.5 range, +1 tear falling speed. Drops a Lucky Penny.+2.5 range. Drops a Lucky Penny.","q":"I remember this...","w":"Dad's Lost Coin","i":"ba81508b5936b2c8d9d6b91b1c5b4158f8c38b69.jpg"},
