  "315":{"n":"Hushy","k":"Passive item","d":"Spawns a Hush familiar that bounces diagonally around the room and deals contact damage. While firing tears, it stops moving. When stationary, Hushy will periodically fire out rings of projectiles.","q":"Lil hush!","w":"Hushy","i":"b303504c7e7d0be257be62c5af10eb7dfbafc0f3.jpg"},
