  "396":{"n":"Brittle Bones","k":"Passive item","d":"Replaces all Red Heart with 6 empty Bone Hearts. Upon losing a Bone Heart, Isaac fires bones in 8 directions and permanently gains a tears up. Upon losing a Bone Heart, Isaac fires bones in 8 directions and permanently gains a fire rate up.","q":"Everything hurts","w":"Brittle Bones","i":"9947731a34c3e81e275c659aa049d31dd1c7d957.jpg"},
