  "400":{"n":"Dad's Ring","k":"Passive item","d":"Creates a ring of light around Isaac that petrifies enemies in contact.","q":"Father's blessing","w":"Dad's Ring","i":"0665c4b67b6b885eed5dafe171c48d11596ba95b.jpg"},
  "401":{"n":"Book of the Dead","k":"Active item","d":"Creates a friendly Bony, Black Bony, or an orbital bone for each enemy killed in the current room. Creates a friendly Bony, Black Bony, Bone Fly, Revenant, Big Bony, or an orbital bone for each enemy killed in the current room.","q":"Rise from the grave","w":"Book of the Dead","i":"2cfba644782ab94d4b1197cbf4b3c84a4732ca28.jpg"},
