  "608":{"n":"Hell Game","k":"Beggar","d":"Hell Game: a devil beggar game where you pay health for a chance at a Devil Room item.","w":"Beggar","i":"2ebcc4132f852c07d68d18714b8affe503a17546.jpg"},
