  "610":{"n":"Wild Card","k":"Card","d":"Copies the effect of the most recently used Pill, Card, Rune, Soul Stone, or activated item.","q":"Again","w":"Wild Card","i":"0b2c618d04bb8a2e4ab0f5a197afdf0f22775a4c.jpg"},
