  "612":{"n":"Fool's Gold","k":"Obstacle","d":"Fool's Gold rock: gold rocks that drop coins when bombed.","w":"Rocks","i":"961c69e1dd2f37c6ec7be8ac5a2ce30a8b3c85fa.jpg"},
  "613":{"n":"Golden Penny","k":"Pickup","d":"Golden Penny: a penny that can drop another coin when picked up.","w":"Coins","i":"7078d220cf995050f9541740cc0f6f078c8aa1d8.jpg"},
  "614":{"n":"Rotten Beggar","k":"Beggar","d":"Rotten Beggar: takes Rotten Hearts or health in exchange for rot-themed rewards and items.","w":"Beggar","i":"4312d3bb508cbfb0dc888adf37743db33b2e0177.jpg"},
  "615":{"n":"Golden Battery","k":"Pickup","d":"Golden Battery: fully charges your active item and gives an extra charge.","w":"Batteries","i":"57fdd097f84929ae6f35a919df8f792580e11576.jpg"},
  "616":{"n":"Confessional","k":"Machine","d":"Confessional: pay hearts to confess and get Eternal Hearts, pickups or angel items.","w":"Machines","i":"17c1994370e586a0833094b90228888ba39ad8a9.jpg"},
