  "618":{"n":"Soul of Isaac","k":"Soul stone","d":"Rerolls all items in the room, but they cycle back to the original item after one second, repeating.","w":"Soul of Isaac","i":"196f6592d033abb12cef197508de871769671686.jpg"},
