  "622":{"n":"Soul of ???","k":"Soul stone","d":"Releases a burst of random poops and farts around Isaac.","w":"Soul of ???","i":"a952dd7ed68c512633f9f38e01a8a07c902164c2.jpg"},
  "623":{"n":"Soul of Eve","k":"Soul stone","d":"Spawns 14 Dead Bird familiars that fly in from off-screen and attack enemies.","w":"Soul of Eve","i":"264b42d8f7b71fadd8c68808e92e99313f2079cb.jpg"},
  "624":{"n":"Soul of Samson","k":"Soul stone","d":"Isaac turns berserk for 10 seconds, replacing Isaac's tears with a melee jawbone club and gaining +0.4 Speed, some Tears, and +3 flat Damage.","w":"Soul of Samson","i":"31505de40c027cc922f151c7fd0ab7bb156d8ac9.jpg"},
  "625":{"n":"Soul of Azazel","k":"Soul stone","d":"Activates Mega Blast for 7.5 seconds.","w":"Soul of Azazel","i":"188816c3514b25d3d2447e46bd0829067a11316f.jpg"},
  "626":{"n":"Soul of Lazarus","k":"Soul stone","d":"Isaac dies, and is immediately revived at half a Heart in the same room, with 1.5 second of invincibility time.","w":"Soul of Lazarus","i":"7615a178f0339f680eccbe84b27c091df4e08f7e.jpg"},
  "627":{"n":"Soul of Eden","k":"Soul stone","d":"Rerolls all pickups, trinkets, and items in the room.","w":"Soul of Eden","i":"b7e70524e315bdc7037dfef64d8749488e554a6d.jpg"},
  "628":{"n":"Soul of the Lost","k":"Soul stone","d":"Turns Isaac into a ghost for the current room as if he touched the White Fire Place in Downpour II / Dross II, temporarily granting The Lost's properties.","w":"Soul of the Lost","i":"8c923ef1a8300dc9d4d648a7e6d3e7a01c7da70a.jpg"},
  "629":{"n":"Soul of Lilith","k":"Soul stone","d":"Grants one permanent familiar from the Baby Shop.","w":"Soul of Lilith","i":"f570ea0edcf5a58c5e25228fe1fb8e44623ff5ea.jpg"},
  "630":{"n":"Soul of the Keeper","k":"Soul stone","d":"Drops 1-25 random Penny on the ground.","w":"Soul of the Keeper","i":"84a207c1641881428d24f418121ac7aec007f91d.jpg"},
  "631":{"n":"Soul of Apollyon","k":"Soul stone","d":"Spawns 15 random locusts.","w":"Soul of Apollyon","i":"54483b37b00308e58733dc1f85f9ca1a9974cccc.jpg"},
  "632":{"n":"Soul of the Forgotten","k":"Soul stone","d":"Spawns The Forgotten as a temporary secondary character, controlled at the same time as Isaac. He dies with no consequences if his health run out, and disappears when Isaac leaves the room. The bone swing deals high damage, and reflects tears.","w":"Soul of the Forgotten","i":"570d7b2e72f4cf60077c12b82a4b2fd0d4cedc4a.jpg"},
  "633":{"n":"Soul of Bethany","k":"Soul stone","d":"Spawns 6 blue wisps.","w":"Soul of Bethany","i":"58aff5a31ebb8b5ea43be42b19fae71fdd23c417.jpg"},
  "634":{"n":"Soul of Jacob and Esau","k":"Soul stone","d":"Spawns Esau as a temporary secondary character, controlled at the same time as Isaac. He dies with no consequences if his health runs out, and disappears when Isaac leaves the room.","w":"Soul of Jacob and Esau","i":"36921ebc754b9937271052dcbf58d07f5dcb2026.jpg"}
